function escapeText(value) {
  return String(value ?? "").replace(
    /[&<>"']/g,
    (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char],
  );
}

// Navigation, controls, actions and metadata are markup generated by the caller.
export function renderPageHeading({
  title,
  count,
  countId = "",
  controls = "",
  actions = "",
  navigation = "",
  metadata = "",
  escapeHtml = escapeText,
}) {
  const counter = count == null ? "" : `<span class="heading-count"${countId ? ` id="${escapeHtml(countId)}"` : ""}>${escapeHtml(count)}</span>`;
  return `<header class="page-heading">${navigation}<div class="page-heading-line"><h1 id="page-title" tabindex="-1">${escapeHtml(title)}${counter}</h1>${controls}</div>${actions || metadata ? `<div class="page-heading-actions">${actions}${metadata}</div>` : ""}</header>`;
}
